import sys, pytest, cachetools
code = cachetools.Cache.__missing__.__code__
class Tracker:
    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_call(self, item):
        hits = 0
        def profile(frame, event, arg):
            nonlocal hits
            if event == 'call' and frame.f_code is code:
                hits += 1
        sys.setprofile(profile)
        yield
        sys.setprofile(None)
        if hits:
            print(f'TARGET_HITS {item.nodeid} {hits}')
pytest.main(['-q', '-s', 'tests/test_cache.py', 'tests/test_cached.py', 'tests/test_cachedmethod.py', 'tests/test_func.py'], plugins=[Tracker()])
PY
